pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint seed) public {
        // Bound the seed to avoid issues with msg.value (TICKET_AMOUNT = 10)
        // We'll use it to control the time and difficulty to force a specific random outcome
        vm.assume(seed > 0);
        // We want random == 0, so we need keccak256(block.timestamp, block.difficulty, msg.sender) % 2 == 0
        // Since we can't control msg.sender easily, we'll just try multiple times by using prank
        // Simpler approach: just call play() with exact value and assume the random could be 0 or 1
        // But to have a deterministic test, we'll try to make random == 0 by adjusting block.timestamp

        // Actually, we can't guarantee which random value we get without controlling block.timestamp/difficulty
        // So we'll just call play() and check the invariant: if random == 0, pot should be 0 at the end (since transfer resets it)
        // The rule is: after play() completes, pot is either unchanged (if random != 0) or 0 (if random == 0)
        // But that's also true for the buggy version? No, buggy version sets pot=0 too.
        // The difference is: in the correct version, bank gets FEE_AMOUNT, and msg.sender gets pot - FEE_AMOUNT, so pot becomes 0.
        // In buggy version, msg.sender gets pot, so pot is 0 as well. So both have pot = 0 after transfer.

        // Wait, the initial statement says pot differs. Let's re-read: P.pot() != M.pot() after a call.
        // If random == 0 in P: pot += 10, then transfer FEE to bank and (pot - FEE) to player, then pot = 0.
        // In M: same but transfer pot to player, then pot = 0. So both end with pot = 0.
        // That can't be it. Maybe the difference is that P has pot = 0 after, M has pot = (something)?
        // Actually, looking again: In P, after transfer(pot - FEE_AMOUNT), the remaining pot is FEE_AMOUNT, then pot = 0.
        // In M, after transfer(pot), pot is still pot (since transfer doesn't change pot), then pot = 0. So both give pot = 0.
        // The real difference: In P, the player receives pot - FEE_AMOUNT, so bank receives FEE_AMOUNT and player gets the rest.
        // In M, player receives pot (which includes the fee), so bank gets FEE_AMOUNT and player gets pot, meaning player gets an extra FEE_AMOUNT.
        // So the property: the total amount sent to bank and player equals the pot before transfer.
        // For P: bank gets FEE_AMOUNT, player gets pot - FEE_AMOUNT, sum = pot = 10 (since pot started 0 and was incremented by 10).
        // For M: bank gets FEE_AMOUNT, player gets pot = 10, sum = 10 + FEE_AMOUNT = 11 > 10, meaning more money is sent than available.
        // But that's not possible because the contract only has 10 wei. So actually M would fail due to insufficient balance if pot is 10 and we try to send 10 to player and 1 to bank (total 11).
        // Unless the contract had extra balance. But with initial balance 0 and sending 10, pot = 10, bank gets 1, player gets 10, total 11, but contract only has 10 -> revert.
        // So the difference is: P always succeeds, M reverts on random == 0 because the transfer to bank fails (insufficient funds).

        // Actually, the transfer to bank happens first: bank.transfer(FEE_AMOUNT). If successful, contract balance becomes 9, then player.transfer(10) fails.
        // So the invariant: after play() with random == 0, the contract should have enough balance to pay both.
        // Let's test with initial pot = 0 and msg.value = 10.

        vm.deal(address(c), 0); // Ensure contract starts with 0 ETH
        vm.deal(address(this), 10); // Give this contract 10 ETH

        uint preBalance = address(this).balance;

        // Call play() - it will either succeed or revert
        // If it succeeds (random == 0 in P, or random != 0 in any), check the invariant
        // The invariant: the caller's balance should have increased by exactly (TICKET_AMOUNT - FEE_AMOUNT) if random == 0, else 0.
        // But we can't know whether random was 0.

        // Alternative: force random == 0 by controlling block.timestamp and difficulty.
        // We can't do that easily in Foundry without vm.warp, vm.difficulty.
        // Let's use a different approach: we can call play() multiple times and check that the contract's balance never goes negative.

        // Actually, the simplest is: after calling play() with exactly 10 wei, if it doesn't revert, then pot must be 0 (since random == 0 case empties it) or unchanged (random == 1 case).
        // But that's same for both.

        // Let's reconsider the difference: The bug is removing FEE_AMOUNT subtraction. 
        // In P: pot += 10 => pot = 10. If random == 0: bank gets 1, player gets 9, pot becomes 0. 
        // In M: bank gets 1, player gets 10, pot becomes 0. But the contract only has 10 wei, so after sending 1 to bank, it has 9 left, can't send 10 to player => revert.
        // So the property: when random == 0, the call should NOT revert. P doesn't revert, M does.

        // Let's test that: the call with msg.value = 10 should not revert if random == 0.
        // But we can't guarantee random == 0. We can use vm.assume to assume we get random == 0? No, that's not possible.

        // Better: check the total amount sent versus what was available.
        // Use a proxy: record the contract's balance before and after, and the caller's balance before and after.
        // For any successful call (no revert), the sum of changes should be 0.

        uint contractBefore = address(c).balance;
        uint callerBefore = address(this).balance;

        (bool success,) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        if (success) {
            uint contractAfter = address(c).balance;
            uint callerAfter = address(this).balance;
            // Total ETH should be conserved: contractBefore + callerBefore = contractAfter + callerAfter
            assertTrue(contractBefore + callerBefore == contractAfter + callerAfter, "ETH conservation violated");
        }
        // If it reverts, we can't check much, but the above covers the bug: 
        // In M, if random == 0, the call would revert (not succeed), so the conservation check is vacuously true.
        // But we want a property that P satisfies and M breaks. For P, the conservation holds for all (successful) calls.
        // For M, if random == 0, the call reverts, so we never get to the assert. That's not breaking.

        // Actually, we need a property that holds for all inputs (including reverts).
        // Let's use a different approach: the bug causes a revert that shouldn't happen.
        // So the property could be: for any valid call (msg.value == 10), the call should NOT revert.
        // P: never reverts for valid input. M: reverts when random == 0.

        // So we can assert that calling play() with 10 wei always succeeds.
        // But that ignores the randomness -> we need to try many times.
        // Since we can't control random, we'll call multiple times and assert at least one succeeds.
        // Actually, the property "the call should never revert" is not true for P if random can be anything,
        // because P never reverts regardless of random.

        // So: For any msg.value == 10, play() should never revert.
        (bool ok,) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        assertTrue(ok, "play() should never revert for correct input");
    }
}

