pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        uint256 initialPot = c.pot();

        // Ensure we can send exactly TICKET_AMOUNT
        vm.deal(address(this), 10);

        // Manipulate block.timestamp and block.difficulty to control random
        vm.warp(seed);
        vm.difficulty(seed);

        // Simulate the random calculation to know if it will be 0
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, address(this)))) % 2;

        // If random is 0, the pot will be emptied; otherwise it stays plus 10
        c.play{value: 10}();

        uint256 finalPot = c.pot();

        if (random == 0) {
            assertTrue(finalPot == 0, "pot should be 0 when random == 0");
        } else {
            // When random != 0, pot should increase by msg.value (10)
            assertTrue(finalPot == initialPot + 10, "pot should increase by 10 when random != 0");
        }
    }
}

