contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Precondition: ensure we have enough balance and the bank can receive ETH
        vm.deal(address(this), 100 ether);
        uint256 initialBankBalance = address(c.bank()).balance;

        // Call play() which may or may not result in random == 0
        // We need to manipulate block.difficulty or use vm.assume to guarantee random == 0
        // Since difficulty is deprecated, we use prevrandao via vm.chainId or other tricks
        // Instead, we just call play() and check after execution
        // If random != 0, nothing happens; we can skip or assume it's 0 by adjusting block values

        // Use vm.assume to force random == 0: we need keccak256(block.timestamp, block.difficulty, msg.sender) % 2 == 0
        // Since block.difficulty is unavailable, we use vm.prevrandao to set a known value
        // Set prevrandao to an even number so (timestamp + prevrandao + sender) % 2 == 0
        // We'll use a fixed seed to guarantee this
        vm.assume(seed % 2 == 0); // seed is used as prevrandao
        vm.prevrandao(bytes32(seed));

        uint256 potBefore = c.pot();

        // Execute play()
        c.play{value: 10}();

        // After execution, if random == 0, bank should have gained exactly FEE_AMOUNT = 1
        if (uint256(keccak256(abi.encodePacked(block.timestamp, seed, address(this)))) % 2 == 0) {
            uint256 bankDelta = address(c.bank()).balance - initialBankBalance;
            assertTrue(bankDelta == 1, "Bank should have gained exactly FEE_AMOUNT");
        }
    }
}

