        vm.deal(caller, 10 ether);

        vm.prank(caller);
        c.play{value: 10}();

        // The rule: after any call, the pot must either be 0 (if win) or 10 (if loss)
        // But the mutant fails because when win happens, the FEE is NOT transferred to bank
        // So the bank's balance doesn't increase by exactly FEE_AMOUNT

