        // Then second call's pot accumulates and bank still gets nothing.

        // The simplest general rule: the difference between reference and mutant is that
        // in reference, after a win, bank balance increases by exactly FEE_AMOUNT (1 wei).

        uint256 bankBefore = c.bank().balance;

        vm.prank(caller);
        c.play{value: 10}();

        uint256 bankAfter = c.bank().balance;
        uint256 potAfter = c.pot();

        // If the caller won (pot is 0 after the call), then bank must have increased by 1
        // If the caller lost (pot is 10), bank balance must stay the same
        assertTrue( (potAfter == 0 && bankAfter == bankBefore + 1) || (potAfter == 10 && bankAfter == bankBefore) );
    }
}

